// Initialize faction management request
const requestData = $input.first().json;
const {
  campaignId,
  action, // 'create', 'update', 'action', 'diplomacy', 'conflict', 'intelligence', 'status'
  factionId,
  targetFactionId,
  actionType,
  actionDetails = {},
  diplomaticTerms = {},
  conflictDetails = {},
  intelligenceData = {},
  statusUpdate = {},
  autoResolve = false
} = requestData;

// Validate required fields
if (!campaignId || !action || !factionId) {
  throw new Error('Missing required fields: campaignId, action, factionId');
}

// Prepare faction operation context
const operationContext = {
  operation_id: `faction_op_${Date.now()}_${Math.random().toString(36).substr(2, 8)}`,
  campaignId,
  action,
  factionId,
  targetFactionId,
  actionType,
  timestamp: new Date().toISOString(),
  autoResolve,
  request_data: {
    actionDetails,
    diplomaticTerms,
    conflictDetails,
    intelligenceData,
    statusUpdate
  },
  processing_context: {
    current_world_state: null,
    faction_data: null,
    target_faction_data: null,
    existing_relationships: null,
    political_context: null
  }
};

return [{ json: operationContext }];

// Process faction context and extract relevant data
const operationContext = $input.first().json;
const worldContext = $input.last().json;

const { worldState, politicalContext, factionHistory } = worldContext.results[0] || {};

// Extract faction data
const factionData = worldState.factions?.find(f => f.id === operationContext.factionId);
if (!factionData) {
  throw new Error(`Faction ${operationContext.factionId} not found in campaign ${operationContext.campaignId}`);
}

// Extract target faction data if applicable
let targetFactionData = null;
if (operationContext.targetFactionId) {
  targetFactionData = worldState.factions?.find(f => f.id === operationContext.targetFactionId);
  if (!targetFactionData) {
    throw new Error(`Target faction ${operationContext.targetFactionId} not found`);
  }
}

// Extract existing relationships
const existingRelationships = factionData.relationships || {};
const relationshipWithTarget = operationContext.targetFactionId ? 
  existingRelationships[operationContext.targetFactionId] : null;

// Analyze political context
const politicalAnalysis = analyzePoliticalContext(factionData, targetFactionData, politicalContext, worldState);

function analyzePoliticalContext(faction, targetFaction, politicalContext, worldState) {
  const analysis = {
    faction_strength: calculateFactionStrength(faction, worldState),
    target_strength: targetFaction ? calculateFactionStrength(targetFaction, worldState) : null,
    power_balance: null,
    alliance_network: analyzeAllianceNetwork(faction, worldState.factions),
    enemy_network: analyzeEnemyNetwork(faction, worldState.factions),
    diplomatic_options: [],
    conflict_risk: 0,
    opportunity_factors: []
  };

  // Calculate power balance
  if (targetFaction) {
    const factionPower = analysis.faction_strength.total_power;
    const targetPower = analysis.target_strength.total_power;
    analysis.power_balance = {
      ratio: factionPower / targetPower,
      advantage: factionPower > targetPower ? 'faction' : targetPower > factionPower ? 'target' : 'equal',
      difference: Math.abs(factionPower - targetPower)
    };
  }

  // Determine diplomatic options
  analysis.diplomatic_options = determineDiplomaticOptions(faction, targetFaction, analysis);

  // Calculate conflict risk
  analysis.conflict_risk = calculateConflictRisk(faction, targetFaction, analysis);

  // Identify opportunity factors
  analysis.opportunity_factors = identifyOpportunityFactors(faction, targetFaction, politicalContext, worldState);

  return analysis;
}

function calculateFactionStrength(faction, worldState) {
  const strength = {
    military: faction.resources?.military_strength || 0,
    economic: faction.resources?.economic_power || 0,
    political: faction.resources?.political_influence || 0,
    magical: faction.resources?.magical_power || 0,
    territory: faction.territories?.length || 0,
    members: faction.members?.length || 0
  };

  // Calculate weighted total power
  strength.total_power = (
    strength.military * 0.3 +
    strength.economic * 0.25 +
    strength.political * 0.25 +
    strength.magical * 0.15 +
    strength.territory * 0.03 +
    strength.members * 0.02
  );

  return strength;
}

function analyzeAllianceNetwork(faction, allFactions) {
  const allies = [];
  const allied_strength = 0;

  Object.entries(faction.relationships || {}).forEach(([factionId, relationship]) => {
    if (relationship > 50) { // Alliance threshold
      const allyFaction = allFactions?.find(f => f.id === factionId);
      if (allyFaction) {
        allies.push({
          id: factionId,
          name: allyFaction.name,
          relationship_strength: relationship,
          reliability: calculateReliability(faction, allyFaction)
        });
        allied_strength += calculateFactionStrength(allyFaction, { factions: allFactions }).total_power;
      }
    }
  });

  return {
    allies,
    ally_count: allies.length,
    allied_strength,
    network_strength: allies.reduce((sum, ally) => sum + (ally.relationship_strength / 100), 0) / Math.max(allies.length, 1)
  };
}

function analyzeEnemyNetwork(faction, allFactions) {
  const enemies = [];
  const enemy_strength = 0;

  Object.entries(faction.relationships || {}).forEach(([factionId, relationship]) => {
    if (relationship < -50) { // Enemy threshold
      const enemyFaction = allFactions?.find(f => f.id === factionId);
      if (enemyFaction) {
        enemies.push({
          id: factionId,
          name: enemyFaction.name,
          hostility_level: Math.abs(relationship),
          threat_level: calculateThreatLevel(faction, enemyFaction)
        });
        enemy_strength += calculateFactionStrength(enemyFaction, { factions: allFactions }).total_power;
      }
    }
  });

  return {
    enemies,
    enemy_count: enemies.length,
    enemy_strength,
    threat_level: enemy_strength / Math.max(calculateFactionStrength(faction, { factions: allFactions }).total_power, 1)
  };
}

function calculateReliability(faction1, faction2) {
  // Calculate reliability based on history, alignment, and interests
  const baseReliability = 0.5;
  const alignmentBonus = faction1.alignment === faction2.alignment ? 0.2 : 0;
  const historyBonus = 0.1; // Would calculate from actual history
  const interestAlignment = calculateInterestAlignment(faction1, faction2);

  return Math.min(baseReliability + alignmentBonus + historyBonus + interestAlignment, 1.0);
}

function calculateThreatLevel(faction, enemyFaction) {
  const factionPower = calculateFactionStrength(faction, { factions: [] }).total_power;
  const enemyPower = calculateFactionStrength(enemyFaction, { factions: [] }).total_power;

  return enemyPower / Math.max(factionPower, 1);
}

function calculateInterestAlignment(faction1, faction2) {
  // Calculate how aligned faction interests are
  const commonGoals = (faction1.goals || []).filter(goal => 
    (faction2.goals || []).includes(goal)
  ).length;

  const totalGoals = Math.max(
    (faction1.goals || []).length,
    (faction2.goals || []).length
  );

  return totalGoals > 0 ? commonGoals / totalGoals : 0;
}

function determineDiplomaticOptions(faction, targetFaction, analysis) {
  const options = [];

  if (!targetFaction) return options;

  const powerRatio = analysis.power_balance?.ratio || 1;
  const currentRelationship = faction.relationships?.[targetFaction.id] || 0;

  // Trade agreement
  if (currentRelationship > -30 && analysis.faction_strength.economic > 20) {
    options.push({
      type: 'trade_agreement',
      feasibility: Math.min(0.8, 0.5 + (currentRelationship / 100)),
      benefits: ['economic_growth', 'relationship_improvement'],
      requirements: ['economic_capacity', 'neutral_or_positive_relations']
    });
  }

  // Military alliance
  if (currentRelationship > 60 && analysis.faction_strength.military > 30) {
    options.push({
      type: 'military_alliance',
      feasibility: Math.min(0.9, 0.4 + (currentRelationship / 100)),
      benefits: ['mutual_defense', 'power_projection'],
      requirements: ['high_trust', 'military_compatibility', 'common_threats']
    });
  }

  // Peace treaty
  if (currentRelationship < -30) {
    options.push({
      type: 'peace_treaty',
      feasibility: Math.min(0.7, 0.3 - (currentRelationship / 200)),
      benefits: ['conflict_resolution', 'reconstruction'],
      requirements: ['mutual_exhaustion', 'mediator', 'concessions']
    });
  }

  // Intelligence sharing
  if (currentRelationship > 20 && powerRatio > 0.5) {
    options.push({
      type: 'intelligence_sharing',
      feasibility: Math.min(0.8, 0.6 + (currentRelationship / 200)),
      benefits: ['improved_situational_awareness', 'coordinated_actions'],
      requirements: ['trust', 'common_interests', 'secure_communications']
    });
  }

  return options;
}

function calculateConflictRisk(faction, targetFaction, analysis) {
  let risk = 0;

  // Base risk from relationship
  const currentRelationship = faction.relationships?.[targetFaction?.id] || 0;
  risk += Math.max(0, (50 - currentRelationship) / 100);

  // Power imbalance risk
  if (analysis.power_balance) {
    const powerImbalance = Math.abs(1 - analysis.power_balance.ratio);
    risk += powerImbalance * 0.3;
  }

  // Enemy network pressure
  risk += analysis.enemy_network.threat_level * 0.2;

  // Strategic goals conflict
  const conflictingGoals = calculateConflictingGoals(faction, targetFaction);
  risk += conflictingGoals * 0.3;

  // External pressures
  if (analysis.opportunity_factors.some(f => f.type === 'external_pressure')) {
    risk += 0.2;
  }

  return Math.min(risk, 1.0);
}

function calculateConflictingGoals(faction1, faction2) {
  const goals1 = faction1.goals || [];
  const goals2 = faction2.goals || [];

  // Simple conflict detection - could be made more sophisticated
  const conflictingPairs = [
    ['territorial_expansion', 'territory_defense'],
    ['resource_control', 'resource_access'],
    ['dominance', 'independence']
  ];

  let conflicts = 0;
  conflictingPairs.forEach(([goal1, goal2]) => {
    if (goals1.includes(goal1) && goals2.includes(goal2)) {
      conflicts++;
    }
    if (goals1.includes(goal2) && goals2.includes(goal1)) {
      conflicts++;
    }
  });

  return Math.min(conflicts / 3, 1.0);
}

function identifyOpportunityFactors(faction, targetFaction, politicalContext, worldState) {
  const factors = [];

  // Power vacuum
  if (worldState.power_vacuum_regions?.length > 0) {
    factors.push({
      type: 'power_vacuum',
      description: 'Power vacuum in certain regions presents expansion opportunities',
      impact: 0.7,
      urgency: 'high'
    });
  }

  // Economic opportunity
  if (worldState.economic_opportunities?.length > 0) {
    factors.push({
      type: 'economic_opportunity',
      description: 'New economic opportunities present growth potential',
      impact: 0.5,
      urgency: 'medium'
    });
  }

  // Alliance opportunity
  if (targetFaction && faction.relationships?.[targetFaction.id] > 30) {
    factors.push({
      type: 'alliance_opportunity',
      description: `Potential for stronger alliance with ${targetFaction.name}`,
      impact: 0.6,
      urgency: 'medium'
    });
  }

  // Weak neighbor
  if (targetFaction && calculateFactionStrength(targetFaction, worldState).total_power < 
                    calculateFactionStrength(faction, worldState).total_power * 0.7) {
    factors.push({
      type: 'weak_neighbor',
      description: `${targetFaction.name} appears weakened and vulnerable`,
      impact: 0.4,
      urgency: 'low'
    });
  }

  return factors;
}

return [{
  json: {
    ...operationContext,
    processing_context: {
      ...operationContext.processing_context,
      current_world_state: worldState,
      faction_data: factionData,
      target_faction_data: targetFactionData,
      existing_relationships: existingRelationships,
      relationship_with_target: relationshipWithTarget,
      political_analysis: politicalAnalysis
    }
  }
}];

// Process faction action execution
const operationContext = $input.first().json;
const { action, actionType, factionId, processing_context } = operationContext;

const { faction_data, political_analysis } = processing_context;

let actionResult = {
  success: false,
  action_executed: false,
  consequences: [],
  world_changes: {},
  political_impact: {},
  narrative_description: ''
};

try {
  switch (actionType) {
    case 'military_campaign':
      actionResult = executeMilitaryCampaign(operationContext);
      break;
    case 'economic_initiative':
      actionResult = executeEconomicInitiative(operationContext);
      break;
    case 'diplomatic_overture':
      actionResult = executeDiplomaticOverture(operationContext);
      break;
    case 'intelligence_operation':
      actionResult = executeIntelligenceOperation(operationContext);
      break;
    case 'internal_policy':
      actionResult = executeInternalPolicy(operationContext);
      break;
    case 'territorial_expansion':
      actionResult = executeTerritorialExpansion(operationContext);
      break;
    case 'resource_acquisition':
      actionResult = executeResourceAcquisition(operationContext);
      break;
    default:
      throw new Error(`Unknown action type: ${actionType}`);
  }
} catch (error) {
  actionResult.error = error.message;
  actionResult.success = false;
}

function executeMilitaryCampaign(context) {
  const { faction_data, target_faction_data, political_analysis } = context.processing_context;
  const { actionDetails } = context.request_data;

  const campaign = {
    type: 'military_campaign',
    target: target_faction_data?.id || 'unknown',
    objectives: actionDetails.objectives || ['territory_control'],
    forces_committed: actionDetails.forces || Math.floor(faction_data.resources?.military_strength * 0.3),
    strategy: actionDetails.strategy || 'direct_assault',
    expected_duration: actionDetails.duration || '1-4 weeks'
  };

  // Calculate success probability
  const successProbability = calculateMilitarySuccessProbability(campaign, political_analysis);
  const success = Math.random() < successProbability;

  // Generate consequences
  const consequences = generateMilitaryConsequences(campaign, success, political_analysis);

  // Calculate political impact
  const politicalImpact = calculateMilitaryPoliticalImpact(campaign, success, political_analysis);

  return {
    success,
    action_executed: true,
    campaign_data: campaign,
    success_probability: successProbability,
    consequences,
    political_impact: politicalImpact,
    world_changes: generateMilitaryWorldChanges(campaign, success),
    narrative_description: generateMilitaryNarrative(campaign, success, faction_data, target_faction_data)
  };
}

function executeEconomicInitiative(context) {
  const { faction_data, political_analysis } = context.processing_context;
  const { actionDetails } = context.request_data;

  const initiative = {
    type: 'economic_initiative',
    initiative_type: actionDetails.initiative_type || 'trade_expansion',
    investment: actionDetails.investment || Math.floor(faction_data.resources?.economic_power * 0.2),
    target_markets: actionDetails.target_markets || ['local'],
    duration: actionDetails.duration || '3-6 months'
  };

  const successProbability = calculateEconomicSuccessProbability(initiative, political_analysis);
  const success = Math.random() < successProbability;

  const consequences = generateEconomicConsequences(initiative, success, political_analysis);
  const politicalImpact = calculateEconomicPoliticalImpact(initiative, success, political_analysis);

  return {
    success,
    action_executed: true,
    initiative_data: initiative,
    success_probability: successProbability,
    consequences,
    political_impact: politicalImpact,
    world_changes: generateEconomicWorldChanges(initiative, success),
    narrative_description: generateEconomicNarrative(initiative, success, faction_data)
  };
}

function executeDiplomaticOverture(context) {
  const { faction_data, target_faction_data, political_analysis } = context.processing_context;
  const { diplomaticTerms } = context.request_data;

  const overture = {
    type: 'diplomatic_overture',
    target_faction: target_faction_data?.id,
    proposal_type: diplomaticTerms.proposal_type || 'alliance',
    terms: diplomaticTerms.terms || {},
    incentives: diplomaticTerms.incentives || [],
    timeline: diplomaticTerms.timeline || 'immediate'
  };

  const successProbability = calculateDiplomaticSuccessProbability(overture, political_analysis);
  const success = Math.random() < successProbability;

  const consequences = generateDiplomaticConsequences(overture, success, political_analysis);
  const politicalImpact = calculateDiplomaticPoliticalImpact(overture, success, political_analysis);

  return {
    success,
    action_executed: true,
    overture_data: overture,
    success_probability: successProbability,
    consequences,
    political_impact: politicalImpact,
    world_changes: generateDiplomaticWorldChanges(overture, success),
    narrative_description: generateDiplomaticNarrative(overture, success, faction_data, target_faction_data)
  };
}

function executeIntelligenceOperation(context) {
  const { faction_data, target_faction_data, political_analysis } = context.processing_context;
  const { intelligenceData } = context.request_data;

  const operation = {
    type: 'intelligence_operation',
    target: target_faction_data?.id,
    operation_type: intelligenceData.operation_type || 'espionage',
    objectives: intelligenceData.objectives || ['information_gathering'],
    resources_committed: intelligenceData.resources || Math.floor(faction_data.resources?.political_influence * 0.2),
    risk_level: intelligenceData.risk_level || 'medium'
  };

  const successProbability = calculateIntelligenceSuccessProbability(operation, political_analysis);
  const success = Math.random() < successProbability;

  const consequences = generateIntelligenceConsequences(operation, success, political_analysis);
  const politicalImpact = calculateIntelligencePoliticalImpact(operation, success, political_analysis);

  return {
    success,
    action_executed: true,
    operation_data: operation,
    success_probability: successProbability,
    consequences,
    political_impact: politicalImpact,
    world_changes: generateIntelligenceWorldChanges(operation, success),
    narrative_description: generateIntelligenceNarrative(operation, success, faction_data, target_faction_data)
  };
}

function executeInternalPolicy(context) {
  const { faction_data, political_analysis } = context.processing_context;
  const { actionDetails } = context.request_data;

  const policy = {
    type: 'internal_policy',
    policy_type: actionDetails.policy_type || 'economic_reform',
    scope: actionDetails.scope || 'faction_wide',
    resources_required: actionDetails.resources || Math.floor(faction_data.resources?.economic_power * 0.1),
    expected_impact: actionDetails.expected_impact || 'moderate'
  };

  const successProbability = calculatePolicySuccessProbability(policy, political_analysis);
  const success = Math.random() < successProbability;

  const consequences = generatePolicyConsequences(policy, success, political_analysis);
  const politicalImpact = calculatePolicyPoliticalImpact(policy, success, political_analysis);

  return {
    success,
    action_executed: true,
    policy_data: policy,
    success_probability: successProbability,
    consequences,
    political_impact: politicalImpact,
    world_changes: generatePolicyWorldChanges(policy, success),
    narrative_description: generatePolicyNarrative(policy, success, faction_data)
  };
}

function executeTerritorialExpansion(context) {
  const { faction_data, target_faction_data, political_analysis } = context.processing_context;
  const { actionDetails } = context.request_data;

  const expansion = {
    type: 'territorial_expansion',
    target_territory: actionDetails.target_territory || 'border_region',
    expansion_method: actionDetails.method || 'peaceful_annexation',
    forces_committed: actionDetails.forces || Math.floor(faction_data.resources?.military_strength * 0.4),
    justification: actionDetails.justification || 'historic_claim'
  };

  const successProbability = calculateExpansionSuccessProbability(expansion, political_analysis);
  const success = Math.random() < successProbability;

  const consequences = generateExpansionConsequences(expansion, success, political_analysis);
  const politicalImpact = calculateExpansionPoliticalImpact(expansion, success, political_analysis);

  return {
    success,
    action_executed: true,
    expansion_data: expansion,
    success_probability: successProbability,
    consequences,
    political_impact: politicalImpact,
    world_changes: generateExpansionWorldChanges(expansion, success),
    narrative_description: generateExpansionNarrative(expansion, success, faction_data, target_faction_data)
  };
}

function executeResourceAcquisition(context) {
  const { faction_data, political_analysis } = context.processing_context;
  const { actionDetails } = context.request_data;

  const acquisition = {
    type: 'resource_acquisition',
    resource_type: actionDetails.resource_type || 'economic',
    acquisition_method: actionDetails.method || 'trade',
    investment: actionDetails.investment || Math.floor(faction_data.resources?.economic_power * 0.3),
    target_quantity: actionDetails.quantity || 'moderate'
  };

  const successProbability = calculateResourceSuccessProbability(acquisition, political_analysis);
  const success = Math.random() < successProbability;

  const consequences = generateResourceConsequences(acquisition, success, political_analysis);
  const politicalImpact = calculateResourcePoliticalImpact(acquisition, success, political_analysis);

  return {
    success,
    action_executed: true,
    acquisition_data: acquisition,
    success_probability: successProbability,
    consequences,
    political_impact: politicalImpact,
    world_changes: generateResourceWorldChanges(acquisition, success),
    narrative_description: generateResourceNarrative(acquisition, success, faction_data)
  };
}

// Success probability calculation functions
function calculateMilitarySuccessProbability(campaign, analysis) {
  let probability = 0.5;

  // Power balance factor
  if (analysis.power_balance) {
    if (analysis.power_balance.advantage === 'faction') {
      probability += 0.2;
    } else if (analysis.power_balance.advantage === 'target') {
      probability -= 0.2;
    }
  }

  // Alliance network factor
  probability += analysis.alliance_network.allied_strength * 0.1;
  probability -= analysis.enemy_network.enemy_strength * 0.05;

  // Force commitment factor
  if (campaign.forces_committed > campaign.forces_committed * 0.5) {
    probability += 0.1;
  }

  // Strategy factor
  const strategyBonus = {
    'direct_assault': 0,
    'siege': 0.1,
    'guerrilla': 0.15,
    'naval_blockade': 0.05
  };
  probability += strategyBonus[campaign.strategy] || 0;

  return Math.max(0.1, Math.min(0.9, probability));
}

function calculateEconomicSuccessProbability(initiative, analysis) {
  let probability = 0.6;

  // Economic strength factor
  probability += (analysis.faction_strength.economic / 100) * 0.2;

  // Investment factor
  if (initiative.investment > 50) {
    probability += 0.1;
  }

  // Market conditions factor
  if (initiative.initiative_type === 'trade_expansion') {
    probability += 0.1;
  }

  return Math.max(0.2, Math.min(0.95, probability));
}

function calculateDiplomaticSuccessProbability(overture, analysis) {
  let probability = 0.5;

  // Current relationship factor
  const currentRelation = analysis.faction_data.relationships?.[overture.target_faction] || 0;
  probability += (currentRelation / 100) * 0.3;

  // Power balance factor
  if (analysis.power_balance && Math.abs(analysis.power_balance.ratio - 1) < 0.3) {
    probability += 0.1;
  }

  // Proposal type factor
  const proposalBonus = {
    'trade_agreement': 0.1,
    'non_aggression_pact': 0.15,
    'alliance': 0.05,
    'intelligence_sharing': 0.2
  };
  probability += proposalBonus[overture.proposal_type] || 0;

  return Math.max(0.1, Math.min(0.9, probability));
}

function calculateIntelligenceSuccessProbability(operation, analysis) {
  let probability = 0.4;

  // Faction political strength
  probability += (analysis.faction_strength.political / 100) * 0.2;

  // Risk level factor
  const riskPenalty = {
    'low': 0,
    'medium': -0.1,
    'high': -0.2,
    'critical': -0.3
  };
  probability += riskPenalty[operation.risk_level] || 0;

  // Operation type factor
  const typeBonus = {
    'espionage': 0,
    'sabotage': -0.1,
    'propaganda': 0.1,
    'counter_intelligence': 0.15
  };
  probability += typeBonus[operation.operation_type] || 0;

  return Math.max(0.1, Math.min(0.8, probability));
}

function calculatePolicySuccessProbability(policy, analysis) {
  let probability = 0.6;

  // Faction stability factor
  if (analysis.faction_strength.political > 50) {
    probability += 0.1;
  }

  // Resource availability factor
  if (policy.resources_required < analysis.faction_strength.economic * 0.2) {
    probability += 0.1;
  }

  // Policy type factor
  const policyBonus = {
    'economic_reform': 0,
    'military_reform': -0.1,
    'social_reform': 0.05,
    'infrastructure': 0.1
  };
  probability += policyBonus[policy.policy_type] || 0;

  return Math.max(0.2, Math.min(0.9, probability));
}

function calculateExpansionSuccessProbability(expansion, analysis) {
  let probability = 0.4;

  // Military strength factor
  probability += (analysis.faction_strength.military / 100) * 0.2;

  // Method factor
  const methodBonus = {
    'peaceful_annexation': 0.2,
    'military_conquest': -0.1,
    'political_manipulation': 0.1,
    'economic_dominance': 0.15
  };
  probability += methodBonus[expansion.expansion_method] || 0;

  // Power balance factor
  if (analysis.power_balance && analysis.power_balance.advantage === 'faction') {
    probability += 0.2;
  }

  return Math.max(0.1, Math.min(0.8, probability));
}

