// Process political narrative and update world state
const operationContext = $input.first().json;
const deepseekResponse = $input.last().json;

let politicalNarrative = {};
try {
  const content = deepseekResponse.choices[0].message.content;
  politicalNarrative = JSON.parse(content);
} catch (error) {
  console.error('Failed to parse DeepSeek political narrative:', error);
  politicalNarrative = {
    narrative_description: operationContext.action_result.narrative_description || 'Political events unfold.',
    player_discovery: 'Players may learn of these events through rumors or observation.',
    player_impact: 'These events may create new opportunities or challenges.',
    foreshadowing: 'Further political developments may follow.',
    key_npcs: []
  };
}

// Update faction data with action results
const updatedFactionData = updateFactionData(
  operationContext.processing_context.faction_data,
  operationContext.action_result,
  operationContext.action_result.world_changes
);

// Update target faction if applicable
let updatedTargetFactionData = null;
if (operationContext.processing_context.target_faction_data) {
  updatedTargetFactionData = updateTargetFactionData(
    operationContext.processing_context.target_faction_data,
    operationContext.action_result,
    operationContext.action_result.political_impact
  );
}

function updateFactionData(factionData, actionResult, worldChanges) {
  const updated = { ...factionData };

  // Update resources based on world changes
  if (updated.resources) {
    updated.resources.military_strength = Math.max(0, 
      (updated.resources.military_strength || 0) + (worldChanges.military_strength || 0) * 100);
    updated.resources.economic_power = Math.max(0, 
      (updated.resources.economic_power || 0) + (worldChanges.economic_power || 0) * 100);
    updated.resources.political_influence = Math.max(0, 
      (updated.resources.political_influence || 0) + (worldChanges.political_influence || 0) * 100);
  }

  // Update territories
  if (worldChanges.territories && worldChanges.territories > 0) {
    updated.territories = [...(updated.territories || []), `territory_${Date.now()}`];
  }

  // Add to action history
  updated.action_history = [
    ...(updated.action_history || []),
    {
      action_id: operationContext.operation_id,
      action_type: actionResult.action_executed ? actionResult.action_type || 'unknown' : 'failed',
      success: actionResult.success,
      timestamp: operationContext.timestamp,
      consequences: actionResult.consequences || [],
      narrative_summary: politicalNarrative.narrative_description
    }
  ];

  // Update relationships
  if (actionResult.political_impact.relationship_changes) {
    updated.relationships = { ...(updated.relationships || {}) };
    actionResult.political_impact.relationship_changes.forEach(change => {
      const currentRelation = updated.relationships[change.target] || 0;
      updated.relationships[change.target] = Math.max(-100, Math.min(100, currentRelation + change.change));
    });
  }

  updated.last_updated = new Date().toISOString();

  return updated;
}

function updateTargetFactionData(targetFactionData, actionResult, politicalImpact) {
  const updated = { ...targetFactionData };

  // Update relationships
  if (politicalImpact.relationship_changes) {
    updated.relationships = { ...(updated.relationships || {}) };
    politicalImpact.relationship_changes.forEach(change => {
      const currentRelation = updated.relationships[operationContext.factionId] || 0;
      updated.relationships[operationContext.factionId] = Math.max(-100, Math.min(100, currentRelation - change.change));
    });
  }

  // Add reaction to action history
  updated.reaction_history = [
    ...(updated.reaction_history || []),
    {
      reacting_to: operationContext.operation_id,
      reaction_type: 'target_of_action',
      impact: politicalImpact,
      timestamp: new Date().toISOString()
    }
  ];

  updated.last_updated = new Date().toISOString();

  return updated;
}

return [{
  json: {
    ...operationContext,
    political_narrative: politicalNarrative,
    world_updates: {
      updated_faction: updatedFactionData,
      updated_target_faction: updatedTargetFactionData,
      world_state_changes: actionResult.world_changes,
      relationship_changes: actionResult.political_impact.relationship_changes || []
    },
    processing_complete: true
  }
}];

// Generate faction action summary
const operationContext = $input.first().json;
const { action_result, political_narrative } = operationContext;

const summary = {
  operation_id: operationContext.operation_id,
  campaign_id: operationContext.campaignId,
  faction_id: operationContext.factionId,
  target_faction_id: operationContext.targetFactionId,
  action_type: operationContext.actionType,
  completion_time: new Date().toISOString(),
  action_summary: {
    success: action_result.success,
    success_probability: action_result.success_probability,
    consequences_count: action_result.consequences?.length || 0,
    political_impact: {
      relationship_changes: action_result.political_impact.relationship_changes?.length || 0,
      power_shift: action_result.political_impact.power_shift || 0,
      reputation_change: action_result.political_impact.reputation_change || 0
    },
    world_changes: {
      military_strength: action_result.world_changes.military_strength || 0,
      economic_power: action_result.world_changes.economic_power || 0,
      political_influence: action_result.world_changes.political_influence || 0,
      territories: action_result.world_changes.territories || 0
    }
  },
  narrative_summary: {
    description: political_narrative.narrative_description || action_result.narrative_description,
    player_discovery: political_narrative.player_discovery || 'Events may be discovered through investigation.',
    player_impact: political_narrative.player_impact || 'Players may be affected by these changes.',
    foreshadowing: political_narrative.foreshadowing || 'Future events may follow from this action.',
    key_npcs: political_narrative.key_npcs || []
  },
  campaign_implications: {
    immediate_effects: action_result.consequences?.map(c => c.description) || [],
    short_term_effects: generateShortTermEffects(action_result),
    long_term_effects: generateLongTermEffects(action_result),
    player_opportunities: generatePlayerOpportunities(political_narrative),
    potential_complications: generatePotentialComplications(action_result)
  },
  next_steps: generateNextSteps(operationContext, action_result)
};

function generateShortTermEffects(actionResult) {
  const effects = [];

  if (action_result.political_impact.relationship_changes) {
    effects.push('Diplomatic relationships will shift immediately');
  }

  if (action_result.world_changes.military_strength && action_result.world_changes.military_strength < 0) {
    effects.push('Military readiness temporarily reduced');
  }

  if (action_result.success && action_result.world_changes.territories > 0) {
    effects.push('New territory requires immediate administration');
  }

  return effects;
}

function generateLongTermEffects(actionResult) {
  const effects = [];

  if (action_result.political_impact.power_shift > 0) {
    effects.push('Regional power balance may shift');
  }

  if (action_result.political_impact.reputation_change > 0) {
    effects.push('Faction reputation enhanced, may attract new allies');
  }

  if (action_result.world_changes.economic_power > 0) {
    effects.push('Economic growth may create new opportunities');
  }

  return effects;
}

function generatePlayerOpportunities(narrative) {
  const opportunities = [];

  if (narrative.player_impact) {
    opportunities.push(narrative.player_impact);
  }

  if (narrative.key_npcs && narrative.key_npcs.length > 0) {
    opportunities.push('New diplomatic contacts available');
  }

  opportunities.push('Information gathering opportunities');

  return opportunities;
}

function generatePotentialComplications(actionResult) {
  const complications = [];

  if (!action_result.success) {
    complications.push('Faction may seek revenge or compensation');
  }

  if (action_result.political_impact.relationship_changes) {
    complications.push('Other factions may react to these changes');
  }

  if (action_result.world_changes.military_strength < -0.15) {
    complications.push('Military weakness may be exploited by enemies');
  }

  return complications;
}

function generateNextSteps(operationContext, actionResult) {
  const steps = [];

  // Immediate follow-up
  steps.push({
    action: 'monitor_reactions',
    description: 'Monitor how other factions react to this action',
    priority: 'high',
    timeline: 'next 24-48 hours'
  });

  // Player involvement
  if (operationContext.processing_context.faction_data.player_allied) {
    steps.push({
      action: 'player_briefing',
      description: 'Brief allied players on action outcomes',
      priority: 'medium',
      timeline: 'next session'
    });
  }

  // World state update
  steps.push({
    action: 'world_state_refresh',
    description: 'Update campaign world state with changes',
    priority: 'high',
    timeline: 'immediate'
  });

  // Future planning
  if (action_result.success) {
    steps.push({
      action: 'strategic_planning',
      description: 'Update faction strategic plans based on success',
      priority: 'medium',
      timeline: 'next week'
    });
  }

  return steps;
}

return [{ json: summary }];
